{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "MESA distinguishes evidence of repeated testing from evidence of stability. Neither is established by one reported run when repetition is unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across repeated runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "Under MESA, explicit non-repetition rules out repeated testing. It leaves score stability unknown rather than demonstrating instability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "A single evaluation provides no evidence of score stability across runs."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "MESA supports both repeated testing and stability for this comparison: conditions were held constant and the observed range meets the stated stability threshold.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under identical stated conditions measured score changes."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed two-percentage-point range meets the specified threshold."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "MESA counts the repeated testing as conducted despite unfavourable results. The observed variation conflicts with the stated definition of stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers tested score changes under the same stated conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range exceeds the stated stability threshold."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "MESA separates documentation supporting repeatability from evidence that repeated evaluations occurred. Installation instructions add no findings about score stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance does not resolve whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no measurements of variation across runs."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "MESA supports the observed comparison within the evaluated grid tasks. Evidence for performance across domains is absent, and the intended use is appropriately narrow.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more evaluated puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "MESA identifies a mismatch between the broad intended use and the narrow evidence. The grid-task comparison remains supported, but the intended use supplies no evidence of general intelligence.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "An intended use involving general intelligence does not establish performance across domains."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "MESA distinguishes initial test scores from later evidence of practical performance. The randomized trial supports decision correctness in the studied workshop, while safety remains unmeasured.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial and reported interval support better correctness with A in the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an improvement in unmeasured workplace safety."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was distinguished from explicit contradiction, and testing occurrence from favourable results."
}
